<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad,onPullDownRefresh,onShow } from '@dcloudio/uni-app'
import { packingApi } from '../../api/packing.api'
import type { PackingShelf } from '../../models/packing'
import SessionTrigger from '@/shared/components/SessionTrigger.vue'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'
import WareState from '@/shared/components/WareState.vue'
import {sessionStore} from '@/store/session'
type TimeOption={label:string;start:string;end:string}
const timeOptions:TimeOption[]=[{label:'全部交货时间',start:'',end:''},{label:'23点半以前',start:'00:00',end:'23:30'},{label:'23:30-00:00',start:'23:30',end:'00:00'},{label:'00:00-00:30',start:'00:00',end:'00:30'},{label:'00:30-01:00',start:'00:30',end:'01:00'},{label:'01:00-01:30',start:'01:00',end:'01:30'},{label:'01:30-02:00',start:'01:30',end:'02:00'},{label:'2点以后',start:'02:00',end:'23:30'}]
const date=ref(new Date().toISOString().slice(0,10)),status=ref(0),keyword=ref(''),restock=ref(false),early=ref(false),boxMatch=ref(0),zone=ref(''),timeIndex=ref(0),rows=ref<PackingShelf[]>([]),zones=ref<string[]>([]),loading=ref(false),pickerVisible=ref(false),zoneVisible=ref(false),timeVisible=ref(false),error=ref('')
const selectedTime=computed(()=>timeOptions[timeIndex.value])
const canStatistics=computed(()=>sessionStore.canAny(['packing.statistics.packaging','packing.statistics.zoneWeight','packing.statistics.income','packing.statistics.cotton']))
async function load(){loading.value=true;error.value='';try{rows.value=await packingApi.shelves({date:date.value,status:status.value,keyword:keyword.value,restock:restock.value,early:early.value,zone:zone.value,boxMatch:boxMatch.value,deliveryStart:selectedTime.value.start,deliveryEnd:selectedTime.value.end});zones.value=await packingApi.zones(date.value)}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function setStatus(value:number){status.value=value;boxMatch.value=0;if(value===3)early.value=false;load()}
function toggleFlag(flag:'restock'|'early',value:boolean){if(flag==='restock')restock.value=!value;else early.value=!value;load()}
function setBoxMatch(value:number){boxMatch.value=boxMatch.value===value?0:value;load()}
function selectZone(value:string){zone.value=value;zoneVisible.value=false;load()}
function selectTime(index:number){timeIndex.value=index;timeVisible.value=false;load()}
function open(row:PackingShelf){uni.navigateTo({url:`/features/packing/pages/task-detail/index?date=${date.value}&shelfSn=${row.shelfSn}`})}
function go(path:string){uni.navigateTo({url:`${path}?date=${date.value}`})}
onLoad(query=>{if(query?.date)date.value=String(query.date);load()});onShow(load);onPullDownRefresh(load)
</script>
<template><view class="page">
  <view class="top"><SessionTrigger :value="date" @click="pickerVisible=true"/><text>打包作业</text></view>
  <view class="shortcuts" :class="{single:!canStatistics}"><view @click="go('/features/packing/pages/my-packages/index')"><strong>我的打包</strong><text>查看本人完成记录 ›</text></view><view v-if="canStatistics" @click="go('/features/packing/pages/statistics/index')"><strong>业务数据统计</strong><text>查看分类统计 ›</text></view></view>
  <view class="query-row"><view class="search"><input v-model="keyword" placeholder="搜索货架" confirm-type="search" @confirm="load"/><text @click="load">查询</text></view><view class="selector" @click="zoneVisible=true"><text>{{zone?`${zone}区`:'全部分区'}}</text><i/></view></view>
  <view class="tab-row"><view class="tabs"><text :class="{active:status===0}" @click="setStatus(0)">可打包</text><text :class="{active:status===1}" @click="setStatus(1)">打包完成</text><text :class="{active:status===3}" @click="setStatus(3)">自提货架</text></view><view class="time-filter" :class="{active:timeIndex>0}" @click="timeVisible=true"><text>{{selectedTime.label}}</text><i/></view></view>
  <view class="filters">
    <view :class="{on:restock}" @click="toggleFlag('restock',restock)"><i>{{restock?'✓':''}}</i><text>只看待补</text></view>
    <view v-if="status!==3" :class="{on:early}" @click="toggleFlag('early',early)"><i>{{early?'✓':''}}</i><text>只看早班</text></view>
    <template v-if="status===1||status===3"><view :class="{on:boxMatch===1}" @click="setBoxMatch(1)"><i>{{boxMatch===1?'✓':''}}</i><text>设箱合规</text></view><view :class="['danger-filter',{on:boxMatch===2}]" @click="setBoxMatch(2)"><i>{{boxMatch===2?'✓':''}}</i><text>设箱不符</text></view></template>
  </view>
  <WareState v-if="loading" type="loading" title="正在加载打包货架"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重新加载" @action="load"/>
  <view v-else-if="rows.length" class="grid"><view v-for="row in rows" :key="row.shelfSn" class="shelf" @click="open(row)"><view class="shelf-head"><strong>{{row.shelfNo}}</strong><view class="badges"><i v-if="row.restockStatus===1" class="restock">待补</i><i v-if="row.earlyShift" class="early">早班</i><i v-if="row.boxMismatch" class="mismatch">设箱不符</i></view></view><text>{{row.completedCount}} / {{row.packageCount}} 包</text><small>{{row.deliveryTime||'未设交货时间'}} · {{row.itemNum}} 扎</small><view class="bar"><i :style="{width:(row.packageCount?row.completedCount/row.packageCount*100:0)+'%'}"/></view></view></view>
  <WareState v-else type="empty" title="暂无符合条件的打包数据" description="可调整分区、交货时间或筛选条件后重试"/>
  <SessionDatePicker v-model="date" v-model:visible="pickerVisible" @confirm="load"/>
  <view v-if="zoneVisible" class="mask" @click="zoneVisible=false"><view class="drawer" @click.stop><view class="handle"/><strong>选择分区</strong><view class="option-grid"><view :class="{active:!zone}" @click="selectZone('')">全部分区</view><view v-for="item in zones" :key="item" :class="{active:zone===item}" @click="selectZone(item)">{{item}}区</view></view></view></view>
  <view v-if="timeVisible" class="mask" @click="timeVisible=false"><view class="drawer time-drawer" @click.stop><view class="handle"/><strong>选择交货时间</strong><view class="option-grid"><view v-for="(item,index) in timeOptions" :key="item.label" :class="{active:timeIndex===index}" @click="selectTime(index)">{{item.label}}</view></view></view></view>
</view></template>
